schema_text:
entity User {};
entity Document { owner: User };
action readDocument appliesTo { principal: [User], resource: [Document], context: {} };
action deleteDocument appliesTo { principal: [User], resource: [Document], context: {} };

property_atoms.reference_cedar:
permit(principal is User, action == Action::"readDocument", resource is Document) when {
    principal == resource.owner
};

approved_atoms.reference_cedar:
permit(principal is User, action == Action::"readDocument", resource is Document) when {
    principal == resource.owner
};
